 export type Document = Readonly<Record<string, string | null>>
+
+const ABSENT: unique symbol = Symbol("absent")
+type Slot = string | null | typeof ABSENT
+
+function has(doc: Document, key: string): boolean {
+  return Object.prototype.hasOwnProperty.call(doc, key)
+}
+
+function slot(doc: Document, key: string): Slot {
+  return has(doc, key) ? (doc[key] as string | null) : ABSENT
+}
+
+function byStringOrder(a: string, b: string): number {
+  return a < b ? -1 : a > b ? 1 : 0
+}
+
 export function merge(base: Document, local: Document, remote: Document): { value: Record<string, string | null>; conflicts: string[] } {
-  return { value: { ...local, ...remote }, conflicts: [] }
+  const keys = new Set<string>()
+  for (const doc of [base, local, remote]) {
+    for (const key of Reflect.ownKeys(doc)) {
+      if (typeof key === "string") keys.add(key)
+    }
+  }
+
+  const value: Record<string, string | null> = {}
+  const conflicts: string[] = []
+
+  for (const key of [...keys].sort(byStringOrder)) {
+    const b = slot(base, key)
+    const l = slot(local, key)
+    const r = slot(remote, key)
+
+    let out: Slot
+    if (l === b) out = r
+    else if (r === b) out = l
+    else if (l === r) out = l
+    else {
+      out = l
+      conflicts.push(key)
+    }
+
+    if (out !== ABSENT) {
+      Object.defineProperty(value, key, {
+        value: out,
+        writable: true,
+        enumerable: true,
+        configurable: true,
+      })
+    }
+  }
+
+  return { value, conflicts }
 }

